const baseUrl = String($env.NPD_AGENT_HUB_ATTRIBUTION_URL || '').replace(/\/$/, '');
const token = String($env.NPD_AGENT_HUB_ATTRIBUTION_TOKEN || '');
if (!baseUrl || !token) throw new Error('Agent Hub attribution environment contract is not configured');
const sequence = Date.now();
const emittedAt = new Date(sequence).toISOString();
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${baseUrl}/api/v1/attribution/deliveries/heartbeats`,
  headers: { Authorization: `Bearer ${token}` },
  body: {
    heartbeat_id: `heartbeat:n8n-lead-intake:${sequence}`,
    producer: 'n8n_lead_intake',
    emitted_at: emittedAt,
    sequence,
    metadata: { workflow: 'lead_intake', environment: 'production' },
    external_writes_enabled: false,
  },
  json: true,
  timeout: 30000,
});
return [{ json: { receipt_id: response.receipt_id, producer: response.producer, received_at: response.received_at, signed: Boolean(response.signature), external_writes_enabled: false } }];
